#include <iostream>
#include <string>
using namespace std;

class Cat {
private:
    string name;
    int fish;

public:
    Cat(string n, int f) : name(n), fish(f) {}

    string getName() const {
        return name;
    }

    int getFish() const {
        return fish;
    }

    void setFish(int f) {
        if (f < 0) {
            return;
        }
        fish = f;
    }
};

int main() {
    Cat c1("{name}", {n});
    c1.setFish({neg});
    cout << c1.getName() << " 有 " << c1.getFish() << " 条" << endl;
    return 0;
}
